<?php foreach (['name'=>'Show name','theatre'=>'Theatre'] as $field=>$label): ?><label class="form-label"><?= e($label) ?><input class="form-control" name="<?= e($field) ?>" value="<?= e($show[$field] ?? '') ?>" maxlength="200" required></label><?php endforeach; ?>
<label class="form-label">Status<select class="form-select" name="status"><?php foreach ($show?App\Services\Shows::STATUSES:['Planning'] as $status): ?><option <?= ($show['status'] ?? '')===$status?'selected':'' ?>><?= e($status) ?></option><?php endforeach; ?></select></label></div></section>
