<?php foreach (App\Services\Shows::CONTACTS as $field): ?><div class="form-grid mb-3"><label class="form-label"><?= e(ucwords(str_replace('_',' ',$field))) ?><input class="form-control" name="<?= e($field) ?>" value="<?= e($show[$field] ?? '') ?>" maxlength="160"></label><label class="form-label">Email (optional)<input class="form-control" type="email" name="<?= e($field) ?>_email" value="<?= e($show[$field . '_email'] ?? '') ?>" maxlength="254"></label><label class="form-label">Phone (optional)<input class="form-control" type="tel" name="<?= e($field) ?>_phone" value="<?= e($show[$field . '_phone'] ?? '') ?>" maxlength="40"></label></div><?php endforeach; ?></div></section>
<section class="card floating-card" data-card-key="show-schedule"><h2 class="floating-label"><span class="material-symbols-rounded" aria-hidden="true">calendar_month</span>Production calendar</h2><div class="card-body form-grid"><?php foreach (App\Services\Shows::DATES as $field): ?><label class="form-label"><?= e(ucwords(str_replace('_',' ',$field))) ?><input class="form-control" type="date" name="<?= e($field) ?>" value="<?= e($show[$field] ?? '') ?>" required></label><?php endforeach; ?></div></section>
<div class="form-error" role="alert" hidden></div><div class="form-actions"><a class="btn" href="<?= $show?'/shows/' . e($show['id']):'/shows' ?>" data-workspace>Cancel</a><button class="btn btn-primary" type="submit">Save show &amp; generate packet</button></div></form>
